// @ts-nocheck
// =====================================================================
// Motion core — Jitter-style animation blocks.
//
// The model (matches jitter.video):
//   • Every layer has an In (appear), Out (disappear) and Loop block.
//   • A preset is a *pose*: the state the layer starts from (In) or
//     ends at (Out). The core interpolates pose → rest with an easing
//     curve, so every animation is guaranteed to land exactly at rest.
//   • Easing presets (Smooth, Slow down, Accelerate, Overshoot,
//     Elastic, Bounce) are all parametric — intensity morphs the curve
//     itself, never the endpoints. Custom cubic-bezier is supported.
//   • Text splits into letter / word / line units. Units are staggered
//     with a delay, an order (forward / reverse / center) and a
//     smoothing value — a secondary easing distributed across units.
//   • Loop blocks only run once a unit has fully entered and blend out
//     before it leaves (enveloped), so entrances stay crisp.
//   • Optional motion blur: fast-moving units leave short ghost trails.
// =====================================================================
import { clamp } from './utils.js';

// ---------------------------------------------------------------------
// easing library — every curve is fn(t, k) with k = intensity (≈0.3–2.5)
// ---------------------------------------------------------------------
export function cubicBezier(x1, y1, x2, y2) {
  // CSS-style cubic-bezier: solve x(t)=u for t, then return y(t)
  const ax = 3 * x1 - 3 * x2 + 1, bx = 3 * x2 - 6 * x1, cx = 3 * x1;
  const ay = 3 * y1 - 3 * y2 + 1, by = 3 * y2 - 6 * y1, cy = 3 * y1;
  const xAt = t => ((ax * t + bx) * t + cx) * t;
  const dxAt = t => (3 * ax * t + 2 * bx) * t + cx;
  const yAt = t => ((ay * t + by) * t + cy) * t;
  return (u) => {
    if (u <= 0) return 0;
    if (u >= 1) return 1;
    let t = u;
    for (let i = 0; i < 6; i++) {           // Newton–Raphson
      const err = xAt(t) - u;
      if (Math.abs(err) < 1e-5) break;
      const d = dxAt(t);
      if (Math.abs(d) < 1e-6) break;
      t = clamp(t - err / d, 0, 1);
    }
    return yAt(t);
  };
}

export const EASINGS = {
  linear:     { label: 'Linear',     fn: (t) => t },
  // AE-style hold keyframe — value jumps at the end, no interpolation
  hold:       { label: 'Hold',       fn: (t) => (t >= 1 ? 1 : 0) },
  // parametric sigmoid — symmetric ease-in-out, k steepens the middle
  smooth:     { label: 'Smooth',     fn: (t, k = 1) => {
    const a = 1.2 + k * 0.9;
    const p = Math.pow(t, a);
    return p / (p + Math.pow(1 - t, a));
  }},
  // ease-out — k deepens the deceleration
  slowdown:   { label: 'Slow down',  fn: (t, k = 1) => 1 - Math.pow(1 - t, 1.6 + k * 1.6) },
  // ease-in — k deepens the acceleration
  accelerate: { label: 'Accelerate', fn: (t, k = 1) => Math.pow(t, 1.6 + k * 1.6) },
  // back-out — k controls how far past the target it flies
  overshoot:  { label: 'Overshoot',  fn: (t, k = 1) => {
    const s = 1.70158 * clamp(k, 0.2, 3);
    const u = t - 1;
    return u * u * ((s + 1) * u + s) + 1;
  }},
  // damped spring — k controls wobble count / tightness
  elastic:    { label: 'Elastic',    fn: (t, k = 1) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    const p = clamp(0.55 - 0.13 * k, 0.18, 0.8);
    return Math.pow(2, -9.5 * t) * Math.sin((t - p / 4) * (2 * Math.PI) / p) + 1;
  }},
  // bounce — k scales the rebound height
  bounce:     { label: 'Bounce',     fn: (t, k = 1) => {
    const n1 = 7.5625, d1 = 2.75;
    let b;
    if (t < 1 / d1) b = n1 * t * t;
    else if (t < 2 / d1) { const u = t - 1.5 / d1; b = n1 * u * u + 0.75; }
    else if (t < 2.5 / d1) { const u = t - 2.25 / d1; b = n1 * u * u + 0.9375; }
    else { const u = t - 2.625 / d1; b = n1 * u * u + 0.984375; }
    // scale the dip below 1, keep endpoints fixed
    return 1 - (1 - b) * clamp(k, 0.2, 2.5);
  }},
  // true damped-oscillator spring (closed-form, not the canned elastic sine
  // decay above) — k is the damping ratio: <1 overshoots, >=1 settles flat.
  // Reads as genuinely "physical" motion rather than an authored wobble.
  spring:     { label: 'Spring',     fn: (t, k = 1) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    const zeta = clamp(k, 0.05, 1.6) * 0.55;      // damping ratio
    const wn = 7.2;                                // fixed natural frequency over t∈[0,1]
    if (zeta < 1) {
      const wd = wn * Math.sqrt(1 - zeta * zeta);
      return 1 - Math.exp(-zeta * wn * t) * (Math.cos(wd * t) + (zeta * wn / wd) * Math.sin(wd * t));
    }
    // critically/over-damped: no overshoot, exponential settle
    return 1 - Math.exp(-zeta * wn * t) * (1 + zeta * wn * t);
  }},
};

export function ease(name, t, intensity = 1, bezier = null) {
  t = clamp(t, 0, 1);
  if (name === 'custom' && bezier && bezier.length === 4) {
    return cubicBezier(bezier[0], bezier[1], bezier[2], bezier[3])(t);
  }
  const e = EASINGS[name] || EASINGS.smooth;
  return e.fn(t, intensity);
}

// ---------------------------------------------------------------------
// per-layer color effects stack (AE effects panel) → canvas filter string.
// Values live in props.fx and apply identically in preview and export.
// ---------------------------------------------------------------------
export function fxFilter(fx) {
  if (!fx) return '';
  const parts = [];
  if (fx.brightness != null && Number(fx.brightness) !== 1) parts.push(`brightness(${fx.brightness})`);
  if (fx.contrast != null && Number(fx.contrast) !== 1) parts.push(`contrast(${fx.contrast})`);
  if (fx.saturate != null && Number(fx.saturate) !== 1) parts.push(`saturate(${fx.saturate})`);
  if (fx.hue) parts.push(`hue-rotate(${fx.hue}deg)`);
  if (fx.sepia) parts.push(`sepia(${fx.sepia})`);
  if (fx.invert) parts.push(`invert(${fx.invert})`);
  return parts.join(' ');
}

// deterministic per-unit random (glitch / scatter looks)
function seeded(i, salt = 1) {
  const x = Math.sin(i * 127.1 + salt * 311.7) * 43758.5453;
  return x - Math.floor(x); // 0..1
}

// ---------------------------------------------------------------------
// pose-based presets.
