//   rest ({} / nothing) at e ≥ 1 so animations always land clean.
// Units: dx/dy in em (font-size for text, min(w,h) for shapes).
// ---------------------------------------------------------------------
export const AT_REST = {
  dx: 0, dy: 0, scale: 1, scaleX: 1, scaleY: 1, rot: 0,
  opacity: 1, blur: 0, clip: null, clipX: null, clipXOrigin: 'left', clipY: null, clipYOrigin: 'top', clipR: null, visible: true, morph: 0,
};

// While the editor is PAUSED, layers render at their rest pose instead of
// wherever their in/out animation happens to be at the playhead. Without
// this, a template inserted at the playhead sat at animation frame 0 —
// opacity 0 / offscreen — so deselecting it made it look like it vanished.
// Playback, export, and the animated template-gallery previews all render
// with this OFF, so real animation is never misrepresented where it matters.
let restPreview = false;
export function setRestPreview(on) { restPreview = !!on; }
// Callers that need the live animated pose while the editor is parked at rest
// (the caption-template fit measures how far a design travels) have to put the
// flag back exactly as they found it.
export function isRestPreview() { return restPreview; }

